"use client";

import type { Transition } from "motion/react";
import {
  animate,
  useInView,
  useMotionValue,
  useMotionValueEvent,
} from "motion/react";
import { useEffect, useRef, useState } from "react";

import { cn } from "@/lib/utils";

interface CounterProps {
  value: number;
  from?: number;
  duration?: number;
  delay?: number;
  decimals?: number;
  prefix?: string;
  suffix?: string;
  separator?: string;
  decimalSeparator?: string;
  transition?: Transition;
  trigger?: "inView" | "auto";
  className?: string;
  onComplete?: () => void;
}

const Counter = ({
  value,
  from = 0,
  duration = 2,
  delay = 0,
  decimals = 0,
  prefix = "",
  suffix = "",
  separator = ",",
  decimalSeparator = ".",
  transition,
  trigger = "inView",
  className,
  onComplete,
  ...props
}: CounterProps & React.HTMLAttributes<HTMLSpanElement>) => {
  const ref = useRef<HTMLSpanElement>(null);
  const inView = useInView(ref, { once: true, amount: 0.5 });
  const motionValue = useMotionValue(from);
  const [displayValue, setDisplayValue] = useState(from);

  useMotionValueEvent(motionValue, "change", (latest) => {
    setDisplayValue(latest);
  });

  useEffect(() => {
    if (trigger === "inView" && !inView) {
      return;
    }

    const controls = animate(motionValue, value, {
      ...transition,
      duration: transition?.duration ?? duration,
      delay,
      ease: transition?.ease ?? [0.16, 1, 0.3, 1],
      onComplete,
    });

    return () => controls.stop();
  }, [
    value,
    from,
    duration,
    delay,
    inView,
    trigger,
    transition,
    motionValue,
    onComplete,
  ]);

  const formatValue = (num: number) => {
    const fixed = num.toFixed(decimals);
    const [int, dec] = fixed.split(".");
    const formattedInt = int.replace(/\B(?=(\d{3})+(?!\d))/g, separator);
    return dec !== undefined
      ? `${formattedInt}${decimalSeparator}${dec}`
      : formattedInt;
  };

  return (
    <span ref={ref} className={cn("tabular-nums", className)} {...props}>
      <span className="sr-only">{`${prefix}${formatValue(value)}${suffix}`}</span>
      <span aria-hidden="true">
        {prefix}
        {formatValue(displayValue)}
        {suffix}
      </span>
    </span>
  );
};

export default Counter;

"use client";

import type { Variants } from "motion/react";
import { AnimatePresence, motion } from "motion/react";
import type { ElementType } from "react";
import { useEffect, useState } from "react";

import { cn } from "@/lib/utils";

interface MorphingTextProps {
  words: string[];
  interval?: number;
  pauseOnHover?: boolean;
  as?: ElementType;
  className?: string;
}

const morphVariants: Variants = {
  initial: { y: 12, opacity: 0, filter: "blur(12px)" },
  animate: {
    y: 0,
    opacity: 1,
    filter: "blur(0px)",
    transition: { duration: 0.5, ease: [0.16, 1, 0.3, 1] },
  },
  exit: {
    y: -12,
    opacity: 0,
    filter: "blur(12px)",
    transition: { duration: 0.3, ease: [0.77, 0, 0.175, 1] },
  },
};

const MorphingText = ({
  words,
  interval = 3000,
  pauseOnHover = false,
  as: Tag = "div",
  className,
  ...props
}: MorphingTextProps & React.HTMLAttributes<HTMLElement>) => {
  const [index, setIndex] = useState(0);
  const [paused, setPaused] = useState(false);

  useEffect(() => {
    if (paused || words.length <= 1) {
      return;
    }

    const id = setInterval(() => {
      setIndex((prev) => (prev + 1) % words.length);
    }, interval);

    return () => clearInterval(id);
  }, [interval, paused, words.length]);

  return (
    <Tag
      className={cn("inline-flex overflow-hidden", className)}
      onMouseEnter={() => pauseOnHover && setPaused(true)}
      onMouseLeave={() => pauseOnHover && setPaused(false)}
      {...props}
    >
      <AnimatePresence mode="wait" initial={false}>
        <motion.span
          key={words[index]}
          variants={morphVariants}
          initial="initial"
          animate="animate"
          exit="exit"
          className="inline-block"
        >
          {words[index]}
        </motion.span>
      </AnimatePresence>
    </Tag>
  );
};

export default MorphingText;

