          <Counter
            value={metric.value}
            prefix={metric.prefix}
            suffix={metric.suffix}
            decimals={metric.decimals}
            duration={2}
          />
        </p>
        <p className="text-sm text-muted-foreground">{metric.label}</p>
      </div>
    ))}
  </div>
);

